'use strict';
(()=>{
const motion=matchMedia('(prefers-reduced-motion: reduce)');const fine=matchMedia('(hover: hover) and (pointer: fine)');
// Keep pointer effects local; native cursor and keyboard behavior remain intact.
document.querySelectorAll('.pill,.contact-nav,.play-circle').forEach(el=>{el.classList.add('magnetic');el.addEventListener('pointermove',e=>{if(motion.matches||!fine.matches)return;const r=el.getBoundingClientRect();el.style.setProperty('--mag-x',Math.max(-9,Math.min(9,(e.clientX-r.left-r.width/2)*.13))+'px');el.style.setProperty('--mag-y',Math.max(-7,Math.min(7,(e.clientY-r.top-r.height/2)*.18))+'px')});const reset=()=>{el.style.setProperty('--mag-x','0px');el.style.setProperty('--mag-y','0px')};el.addEventListener('pointerleave',reset);el.addEventListener('blur',reset);motion.addEventListener('change',reset)});
document.querySelectorAll('.project-image').forEach(el=>{el.addEventListener('pointermove',e=>{if(motion.matches||!fine.matches)return;const r=el.getBoundingClientRect();el.style.setProperty('--cursor-x',e.clientX-r.left+'px');el.style.setProperty('--cursor-y',e.clientY-r.top+'px')})});
const glow=document.querySelector('.contact');glow.addEventListener('pointermove',e=>{if(motion.matches||!fine.matches)return;const r=glow.getBoundingClientRect();glow.style.setProperty('--glow-x',e.clientX-r.left+'px');glow.style.setProperty('--glow-y',e.clientY-r.top+'px')});
const progress=document.querySelector('.reading-progress>span');let queued=false;const update=()=>{const max=document.documentElement.scrollHeight-innerHeight;progress.style.transform=`scaleX(${max>0?Math.min(1,Math.max(0,scrollY/max)):0})`;queued=false};addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(update)}},{passive:true});addEventListener('resize',update);update();
document.querySelectorAll('[data-finish]').forEach(button=>{button.addEventListener('click',()=>{document.querySelectorAll('[data-finish]').forEach(b=>{b.classList.toggle('selected',b===button);b.setAttribute('aria-pressed',String(b===button))});const host=document.querySelector('#sculpture');host.dataset.finish=button.dataset.finish;host.dispatchEvent(new CustomEvent('lume-finish',{detail:button.dataset.finish}))})});
})();
